from __future__ import annotations

import json
import os
from typing import TYPE_CHECKING, TypedDict, cast

if TYPE_CHECKING:
    from typing import NotRequired


class Env(TypedDict):
    """Coerced env schema (matches varlock coercion) — values are typed, not raw strings."""
    # API key for Opencode (used by both Zen and Go providers)
    # Docs: https://opencode.ai
    OPENCODE_API_KEY: NotRequired[str]
    # API key for OpenRouter
    # Docs: https://openrouter.ai/docs/api_reference/authentication
    OPENROUTER_API_KEY: NotRequired[str]


# Keys whose values are sensitive — use this to build your own redaction / leak-scanning.
SENSITIVE_KEYS: frozenset[str] = frozenset({"OPENCODE_API_KEY", "OPENROUTER_API_KEY"})


def load_env() -> Env:
    """Parse the `__VARLOCK_ENV` blob (injected by `varlock run`) into typed, coerced values."""
    blob = os.environ.get("__VARLOCK_ENV")
    if not blob:
        raise RuntimeError("__VARLOCK_ENV is not set — run your program via `varlock run` (note: `--inject vars` omits the blob this module needs)")
    if blob.startswith("varlock:v1:"):
        raise RuntimeError("__VARLOCK_ENV is encrypted and this generated module cannot decrypt it — disable @encryptInjectedEnv for processes using a generated env module")
    graph = json.loads(blob)
    # unset optional keys are omitted from the blob (no "value"), so skip them here —
    # matches the TypedDict `NotRequired` contract (key absent, not present-as-None)
    return cast(
        Env,
        {key: entry["value"] for key, entry in graph["config"].items() if "value" in entry},
    )
